 function requestPreview(r,buttons){
  const people=directory.filter(person=>person.id!==user.id&&
   (person.role==='admin'||person.scopes.includes(r.company))&&person.permissions?.previewRequest);
  const panel=el('section',{class:'preview-request-panel'});
  const recipient=el('select',{'aria-label':'الموظف المطلوب منه المعاينة'});
  recipient.append(option('','اختر موظفًا للمعاينة'));
  for(const person of people)recipient.append(option(person.id,person.name));
  const note=el('textarea',{'aria-label':'ملاحظة المعاينة',maxlength:'500',placeholder:'ملاحظة للموظف (اختياري)'});
  const status=el('p',{role:'status',class:'note'});
  const send=el('button',{type:'button',class:'primary'},'إرسال طلب المعاينة');
  send.disabled=!people.length;
  if(!people.length)status.textContent='لا يوجد موظف آخر لديه صلاحية معاينة لهذه الشركة.';
  send.onclick=async()=>{
   if(!recipient.value){status.textContent='اختر الموظف الذي سيعاين الطلب.';recipient.focus();return;}
   send.disabled=true;
   try{
    if(!await persist())throw Error('تعذر حفظ التعديلات قبل إرسال المهمة.');
    const response=await request('/api/inbox/preview',{method:'POST',headers:{'Content-Type':'application/json'},
     body:JSON.stringify({recordId:r.id,revision:r.revision,recipientId:recipient.value,message:note.value})});
    const result=await response.json();
    status.textContent=result.existing?'توجد مهمة معاينة معلّقة لهذا الموظف.':'ظهر طلب المعاينة في إشعارات الموظف.';
   }catch(e){status.textContent=e.message;}
   finally{send.disabled=false;}
  };
  panel.append(recipient,note,send,status);
  buttons.after(panel);
  recipient.focus();
 }

 async function openInboxRequest(id){
  if(!await persist())throw Error('تعذر حفظ التعديلات الحالية.');
  const latest=await(await request('/api/state')).json();
  const records=Object.values(latest.state.archives).flat();
  const record=records.find(item=>item.id===id);
  if(!record)throw Error('الطلب غير متاح لحسابك.');
  if(!state.editSession&&!dirty){
   state.archives=latest.state.archives;
   serverView=latest.view;
   revision=latest.revision;
   draw();
   oldArchive();
  }
  chooseView('tracking');
  await detail(state.editSession?(all().find(item=>item.id===id)||record):record);
 }

 async function openInboxPreview(id){
  const task=await(await request('/api/inbox/preview?task='+encodeURIComponent(id))).json();
  openRequestPreview(task.record,task.completed?null:id);
 }
